#!/usr/bin/env bash
# =============================================================================
# run_dtu_netmhcpan_official.sh — netMHCpan-4.1 -BA (→BA+EL) + netMHCstabpan-1.0
#   on NEW official inputs. Service: quantimmu-bench / node tools_dtu (W1).
# =============================================================================
# Inputs (uploaded to HPC): $IN/<allele_safe>.pep + allele_map.tsv
#   (generated by prep_netmhcpan_ba.py on master_backbone_official.csv)
#
# Per allele:
#   1) netMHCpan -p <pep> -BA -a <nmhc> -xls -xlsfile <safe>_ba.xls
#      → -BA -xls 输出同时含 EL-score, EL_Rank, BA-score, BA_Rank 列
#        ⇒ 一次跑出 netMHCpan_BA + netMHCpan_EL 两工具的分。
#   2) netMHCstabpan -p <pep> -a <nmhc> -xls -xlsfile <safe>_stab.xls
#      → -xls 列: Pos Peptide ID Pred Thalf(h) Rank Ave NB（用 Pred,越高越稳）
#      stabpan 在 HPC 登录节点 glibc 2.28 下 W1 已 smoke 直跑通,无需容器/net.sif。
#
# 直跑: bash run_dtu_netmhcpan_official.sh   (CPU,快,~1600肽×26等位)
# =============================================================================
set -u

ROOT=/gpfs/work/bio/jiayu2403/quantimmu
NETMHCPAN=${ROOT}/ext_tools/netMHCpan-4.1/netMHCpan
STABPAN=${ROOT}/ext_tools/netMHCstabpan-1.0/netMHCstabpan
IN=${ROOT}/ds1/dtu_netmhcpan_inputs
BA_OUT=${IN}/ba_out
STAB_OUT=${IN}/stab_out
ALLELE_MAP=${IN}/allele_map.tsv

mkdir -p "${BA_OUT}" "${STAB_OUT}" "${ROOT}/ext_tools/netMHCpan-4.1/tmp" "${ROOT}/ext_tools/netMHCstabpan-1.0/tmp"

[ -x "$NETMHCPAN" ] || { echo "[FATAL] netMHCpan missing: $NETMHCPAN"; exit 1; }
[ -x "$STABPAN" ]   || { echo "[FATAL] netMHCstabpan missing: $STABPAN"; exit 1; }
[ -f "$ALLELE_MAP" ] || { echo "[FATAL] allele_map.tsv missing: $ALLELE_MAP"; exit 1; }

n_ba=0; n_stab=0; n_fail=0
while IFS=$'\t' read -r safe nmhc; do
    [ -z "$safe" ] && continue
    pep="${IN}/${safe}.pep"
    [ -s "$pep" ] || { echo "[SKIP] $safe no pep"; continue; }
    npep=$(wc -l < "$pep")

    # --- netMHCpan -BA (gives BA + EL) ---
    if "$NETMHCPAN" -p "$pep" -BA -a "$nmhc" -xls -xlsfile "${BA_OUT}/${safe}_ba.xls" >/dev/null 2>&1; then
        echo "[BA ] $nmhc ($npep) OK"; n_ba=$((n_ba+1))
    else
        echo "[BA ] $nmhc FAIL"; n_fail=$((n_fail+1))
    fi

    # --- netMHCstabpan (Pred stability) ---
    if "$STABPAN" -p "$pep" -a "$nmhc" -xls -xlsfile "${STAB_OUT}/${safe}_stab.xls" >/dev/null 2>&1; then
        echo "[STB] $nmhc ($npep) OK"; n_stab=$((n_stab+1))
    else
        echo "[STB] $nmhc FAIL"; n_fail=$((n_fail+1))
    fi
done < "$ALLELE_MAP"

echo "[DONE] BA xls=$n_ba  STAB xls=$n_stab  fail=$n_fail"
echo "[DONE] BA_OUT=${BA_OUT}  STAB_OUT=${STAB_OUT}"
ls "${BA_OUT}" | wc -l | sed 's/^/ba_out files: /'
ls "${STAB_OUT}" | wc -l | sed 's/^/stab_out files: /'
